/* ==UserStyle==
@name         Roblox Safe Full Light Pink
@namespace    roblox-safe-pink
@version      1.0
@match        https://www.roblox.com/*
==/UserStyle== */

/* Fill entire page with light pink */
html, body {
    background-color: #ffe4ec !important; /* very light pink */
    color: #4a2c3a !important;
}

/* Full viewport overlay */
html::before, body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: #ffe4ec !important; /* light pink sides */
    z-index: -1;
}

/* Text and links */
body, h1, h2, h3, p, span, a {
    color: #4a2c3a !important;
}

a {
    color: #ff9ac2 !important;
}
